# Every bold label the spec prints on a feature section falls in one of these two sets, and
# `test_every_spec_label_is_either_audited_or_declared_out_of_scope` asserts that against the spec.
#
# It is asserted rather than described because the first version of this module knew *six* labels
# and called its coverage total. The spec prints seventy-four, and §8.2 FND-001's ten-item content
# list sits under `**Data displayed per facility:**` — a label the module had never heard of, in the
# section whose Outputs it had just finished auditing. An instrument that cannot see a label cannot
# measure it, and the number it reports is then a fact about the instrument rather than about the
# spec. The partition is what makes a missing label a failure instead of an undercount.
#
# `_LABELS` is the content set: a label whose body enumerates things the feature *does or holds*,
# so each item is a claim the code can be crossed against. `_CLAIM_LABELS` is the other kind — a
# sentence *about* the feature (its tier, its data source, its privacy stance, its battery cost)
# rather than a list of what it does. Those are auditable in principle and are not audited here;
# the test names them so the boundary is a decision on the record, not an omission.
#
# The line between the two is the *shape of the body*, and the test asserts it rather than taking
# the sets on trust: a label in `_CLAIM_LABELS` whose body is a bullet list is a content list
# miscategorised, and the sections it sits on are then reported as having nothing to audit.
# Eight labels were exactly that — `Application` (§SEC-002), `Behaviour` (§EMG-002, §LOC-004),
# `Conditions supported` (§MON-003), `Deployment points` (§LOC-004), `How it works` (§LOC-003),
# `Privacy properties` (§LOC-002), `Standards` (§SEC-003) and `Technical approach` (§ACC-003,
# §ACC-004) — and they were the whole of the eight sections this module called contentless. With
# them moved across, the audit covers all 69 `#### FID:` sections in the spec and has no
# unlabelled section left to explain.
_LABELS: tuple[str, ...] = (
	'Access', 'Additional features over REC-001', 'Additional inputs', 'Alert content', 'Anti-gaming', 'Application',
	'Behaviour', 'Conditions supported', 'Consent categories', 'Content', 'Contents',
	'Data displayed per facility', 'Deployment points', 'Displays', 'Entry questions', 'Features',
	'Format', 'How it works', 'Inputs', 'Options', 'Output', 'Outputs', 'Privacy properties',
	'Reportable items', 'Signals monitored', 'Standards', 'Targets', 'Technical approach',
	'Test types (context-dependent)', 'Topics', 'User rights',
	# §5's seven channel sections and §14.9's two sensor sections print these. They were missing from
	# the vocabulary *and* the sections were missing from the reader, so the two defects hid each
	# other: a label the audit does not know is invisible only in a section it does not read, and a
	# section it does not read is invisible only while its labels are unknown. Widening the reader
	# without widening this would have failed the vocabulary partition instead of silently
	# under-reading, which is the one good thing about having both tests.
	'Applications', 'Constraints', 'Content formats', 'Content types', 'Inbound use cases',
	'Menu structure (illustrative)', 'Outbound use cases', 'Supported devices',
	'Target intermediaries', 'Tools provided', 'Why WhatsApp is the primary product',
)

# Labels that state something *about* a feature rather than listing what it does. Declared here so
# the spec's whole label vocabulary is accounted for and a new label cannot be added to the spec
# without someone deciding which side of this line it falls on.
_CLAIM_LABELS: tuple[str, ...] = (
	'Access control', 'Accessibility', 'Adherence design', 'Alerting', 'Battery',
	'Battery impact', 'Benefit', 'Clinical basis', 'Configuration', 'Consumers', 'Data flow',
	'Data handling', 'Data source', 'Data sources', 'Delivery', 'Description', 'Design',
	'Disclaimer', 'Escalation', 'Flow', 'Follow-up', 'Integration', 'Languages', 'Limitations',
	'Offline', 'Privacy', 'Reference', 'Rollout', 'Sensitivity', 'Support', 'Target user',
	'Target users', 'Tier', 'Tier 1 behaviour', 'Tier 4 behaviour', 'Tone', 'Training',
	'User control', 'Value', 'Verification', 'Why this feature',
	'Why this matters for outbreaks', 'Why this works',
	# The same widening, the other side of the line. Each of these is a sentence or a table about the
	# feature, and the shape rule in `test_a_label_declared_out_of_scope_has_no_list_under_it` is what
	# put them here rather than a judgement: `Capabilities` (§CHAN-3) is a markdown table, and the
	# rest carry no bullet or numbered list.
	'Capabilities', 'Critical requirement', 'Distribution', 'Feature ID', 'Language coverage',
	'Measurement', 'Objectives', 'Rationale', 'Role', 'Session limits',
)

# Every section in the spec is audited above, so this list is empty. It is kept, and asserted
# against the spec's own section count, rather than deleted: the *empty* list is the claim of
# coverage, and a reader is entitled to see the mechanism that would name a section the day one is
# added to the spec and not to this table. §19.4 is the one section outside the spec's `#### FID:`
# sections that prints an `**Access:**` label, and it is out of this module's declared scope rather
# than unaudited — the partition test counts the `#### FID:` sections, and §19.4 is not one.
UNAUDITED_FEATURES: tuple[str, ...] = ()

assert not (set(UNAUDITED_FEATURES) & {f for f, _, _, _, _, _ in FEATURE_CONTENT}), \
	'a feature is either audited or listed as unaudited, never both'

assert all(kind in ('carried', 'deferred', 'missing') for _, _, _, kind, _, _ in FEATURE_CONTENT), \
	'every bullet has one of the three verdicts'
assert all(ref for _, _, _, kind, ref, _ in FEATURE_CONTENT if kind == 'carried'), \
	'a carried bullet must name the code that carries it'
assert all(note for _, _, _, kind, _, note in FEATURE_CONTENT if kind != 'carried'), \
	'a deferred or missing bullet must say why'
assert all(label in _LABELS for _, label, _, _, _, _ in FEATURE_CONTENT), \
	'every label is one of the content labels the spec uses'

assert all(kind in ('carried', 'deferred', 'narrative') for _, _, _, kind, _, _ in CLAIM_CONTENT), \
	'every claim has one of the three claim verdicts'
assert all(ref for _, _, _, kind, ref, _ in CLAIM_CONTENT if kind == 'carried'), \
	'a carried claim must name the code that carries it'
assert all(note for _, _, _, kind, _, note in CLAIM_CONTENT if kind != 'carried'), \
	'a deferred or narrative claim must say why'
assert all(label in _CLAIM_LABELS for _, label, _, _, _, _ in CLAIM_CONTENT), \
	'every claim label is one of the claim labels the spec uses'
assert all(label not in _LABELS for _, label, _, _, _, _ in CLAIM_CONTENT), \
	'the two vocabularies are a partition, so a claim label is never a content label'
# The metadata labels carry no claim: a `Description` restates the section's heading and a `Tier` is
# a position in §7's ladder. Reading them would put the spec's own index into the audit.
assert not ({'Description', 'Feature ID', 'Tier'} & {label for _, label, _, _, _, _ in CLAIM_CONTENT}), \
	'a metadata label is not a claim'


def content_report() -> FeatureContentReport:
	"""Every audited feature section, its bullets, and the three verdicts separated.

	`missing` is the finding and it is reported, not repaired: whether an absent bullet is a gap or
	a deliberate deferral is a product decision. `unresolved` is a different finding — a `carried`
	reference that does not import is a bullet whose carrier rotted, not one nobody built.
	"""
	features: list[FeatureContent] = []
	for feature_id in dict.fromkeys(f for f, _, _, _, _, _ in FEATURE_CONTENT):
		bullets = [
			ContentBullet(label=label, bullet=bullet, kind=kind, carried_by=ref,
				resolves=resolves(ref) if ref else False, note=note)
			for f, label, bullet, kind, ref, note in FEATURE_CONTENT if f == feature_id
		]
		features.append(FeatureContent(
			feature_id=feature_id, bullets=bullets,
			missing=[b.bullet for b in bullets if b.kind == 'missing'],
			carried_count=sum(1 for b in bullets if b.kind == 'carried'),
		))
	return FeatureContentReport(
		features=features,
		missing=[f'§{f.feature_id}: {m}' for f in features for m in f.missing],
		unresolved=[f'§{f.feature_id}: {b.carried_by}' for f in features for b in f.bullets
			if b.carried_by and not b.resolves],
		audited_features=len(features),
		unaudited_features=list(UNAUDITED_FEATURES),
	)


def claim_report() -> ClaimContentReport:
	"""The claim side of the audit — every passage the claim labels print, and its verdict.

	`unresolved` is the finding, and it is the one this report was built for: a `carried` claim whose
	reference no longer imports is a claim about the code that stopped being true. `narrative` and
	`deferred` are counted rather than listed, because a list of thirty-eight sentences about
	adoption would read as thirty-eight gaps.

	The coverage statement is `pairs_read` against the spec's own count, which is what
	`test_every_claim_label_a_section_prints_has_a_verdict_under_it` asserts: the report says how much
	of the claim side it read rather than inviting a reader to take the totals as complete.
	"""
	pairs = dict.fromkeys((f, label) for f, label, _, _, _, _ in CLAIM_CONTENT)
	sections = [
		ClaimContent(
			feature_id=f, label=label,
			claims=[claim for ff, ll, claim, _, _, _ in CLAIM_CONTENT if (ff, ll) == (f, label)],
			kinds={k: sum(1 for ff, ll, _, kk, _, _ in CLAIM_CONTENT
				if (ff, ll) == (f, label) and kk == k) for k in ('carried', 'deferred', 'narrative')},
		)
		for f, label in pairs
	]
	return ClaimContentReport(
		sections=sections,
		pairs_read=len(pairs),
		claims_read=len(CLAIM_CONTENT),
		carried=sum(1 for _, _, _, k, _, _ in CLAIM_CONTENT if k == 'carried'),
		deferred=sum(1 for _, _, _, k, _, _ in CLAIM_CONTENT if k == 'deferred'),
		narrative=sum(1 for _, _, _, k, _, _ in CLAIM_CONTENT if k == 'narrative'),
		unresolved=[f'§{f}: {ref}' for f, _, _, k, ref, _ in CLAIM_CONTENT
			if k == 'carried' and ref and not resolves(ref)],
	)
